<?php require_once 'includes/auth.php';if(current_user()){header('Location: account.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$s=$pdo->prepare("SELECT * FROM users WHERE email=? LIMIT 1");$s->execute([trim($_POST['email'])]);$u=$s->fetch();if($u&&$u['status']==='active'&&password_verify($_POST['password'],$u['password'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];flash('success','Welcome back, '. $u['name'].'!');header('Location: '.($u['role']==='admin'?'admin/':'account.php'));exit;}flash('error','Invalid email or password.');} $page_title='Login';require 'includes/header.php';?>
